{
  "findings": [
    {
      "check_id": "CKV_GCP_83",
      "title": "Ensure PubSub Topics are encrypted with Customer Supplied Encryption Keys (CSEK)",
      "resource": "google_pubsub_topic.notification_queue",
      "severity": "MEDIUM",
      "explanation": "The PubSub topic is not configured to use a Customer Supplied Encryption Key (CSEK). Without CSEK, data is encrypted using Google-managed keys, which may not meet compliance or organizational security requirements."
    }
  ],
  "patched_code": "resource \"google_pubsub_topic\" \"notification_queue\" {\n  name = \"insurance-claims-processing-platform-pubsub-notifications\"\n  labels = {\n    environment = \"production\"\n    component   = \"notifications\"\n  }\n\n  kms_key_name = \"projects/my-project/locations/global/keyRings/my-keyring/cryptoKeys/my-key\"\n}",
  "fix_summary": "Added the 'kms_key_name' attribute to the PubSub topic resource to enforce encryption with a Customer Supplied Encryption Key (CSEK)."
}
